l 10px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="ctivity.font.color" description="Activity Color" type="color" default="#333" value="#333333"/> <Variable name="about.text.font" description="Text Font" type="font" default="normal normal 13px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="normal normal 13px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="about.text.color" description="About Text Color" type="color" default="#555" value="#555555"/> <Variable name="icons.color" description="Icons Color" type="color" default="#333" value="#333333"/> <Variable name="icons.hover.color" description="Icons Hover Color" type="color" default="#fff" value="#ffffff"/> <Variable name="icons.hover.background" description="Icons Hover Background" type="color" default="#333" value="#333333"/> </Group> <Group description="Portfolio" selector="portfolio"> <Variable name="portfolio.title.background" description="Title Background" type="color" default="#333" value="#87ba45"/> <Variable name="portfolio.title.color" description="Title Color" type="color" default="#fff" value="#ffffff"/> <Variable name="portfolio.text.color" description="Text Color" type="color" default="#fff" value="#ffffff"/> <Variable name="portfolio.image.background" description="Image Hover Background" type="color" default="#ff7777" value="#87ba45"/> <Variable name="portfolio.icons.color" description="Icons Color" type="color" default="#fff" value="#ffffff"/> <Variable name="portfolio.hover.icons.color" description="Icons Hover Color" type="color" default="#333" value="#333333"/> <Variable name="portfolio.icons.hover.background" description="Icons Hover Background" type="color" default="#fff" value="#ffffff"/> </Group> <Group description="Clients" selector="clients"> <Variable name="clients.title.background" description="Title Background" type="color" default="#fff" value="#ff9900"/> <Variable name="clients.title.color" description="Title Color" type="color" default="#222" value="#222222"/> <Variable name="clients.text.color" description="Clients Text Color" type="color" default="#555" value="#555555"/> </Group> <Group description="Blog" selector="blog"> <Variable name="blog.background" description="Blog Background" type="color" default="#eee" value="#eeeeee"/> <Variable name="blog.title.color" description="Title Color" type="color" default="#222" value="#222222"/> <Variable name="blog.descrption.title.color" description="Description Title Color" type="color" default="#555" value="#555555"/> <Variable name="date.background" description="Date Background" type="color" default="#ff7777" value="#ff7777"/> <Variable name="day.color" description="Day Color" type="color" default="#fff" value="#ffffff"/> <Variable name="month.color" description="Month Color" type="color" default="#fff" value="#ffffff"/> <Variable name="blog.caption" description="Blog Caption Background" type="color" default="#fff" value="#ffffff"/> <Variable name="blog.caption.border" description="Blog Caption Border" type="color" default="#e7e7e7" value="#e7e7e7"/> <Variable name="post.title.font" description="Post Title Font" type="font" default="300 18px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="normal normal 18px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="post.title.color" description="Post Title Color" type="color" default="#222" value="#222222"/> <Variable name="post.title.hover.color" description="Post Title Hover Color" type="color" default="#ff7777" value="#ff7777"/> <Variable name="post.text.font" description="Post Text Font" type="font" default="normal normal 14px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="normal normal 14px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="post.text.color" description="Post Text Color" type="color" default="#555" value="#555555"/> <Variable name="author.font" description="Author Font" type="font" default="normal 11px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="normal normal 11px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="author.color" description="Author Color" type="color" default="#333" value="#333333"/> <Variable name="author.text" description="Author Text" type="font" default="italic 300 10px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="italic normal 12px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="author.text.color" description="Author Text Color" type="color" default="#555" value="#555555"/> </Group> <Group description="Ribbon" selector="ribbon"> <Variable name="attent.background.color" description="Ribbon Background Color" type="color" default="#ff7777" value="#3d85c6"/> <Variable name="attent.text" description="Blog Ribbon Text" type="font" default="300 25px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="normal normal 28px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="attent.text.color" description="Ribbon Text Color" type="color" default="#fff" value="#ffffff"/> <Variable name="attent.button.background" description="Button Background" type="color" default="#333" value="#87ba45"/> <Variable name="attent.button.hover.border" description="Button Hover Border" type="color" default="#fff" value="#93c47d"/> <Variable name="attent.button.hover.color" description="Button Hover Color" type="color" default="#fff" value="#ff9900"/> </Group> <Group description="Contact Form" selector="contact"> <Variable name="contact.background.color" description="Background Color" type="color" default="#eee" value="#eeeeee"/> <Variable name="form.control.background.color" description="Inputs Color" type="color" default="#fff" value="#ffffff"/> <Variable name="form.title.color" description="Title Color" type="color" default="#222" value="#222222"/> <Variable name="form.border.color" description="Border Color" type="color" default="#ccc" value="#cccccc"/> <Variable name="form.text.color" description="Text Color" type="color" default="#555" value="#555555"/> <Variable name="form.text.font" description="Text Font" type="font" default="normal normal 13px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="normal normal 13px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="form.button.background" description="Button Background" type="color" default="#333" value="#87ba45"/> <Variable name="form.button.background.hover" description="Hover Button Background" type="color" default="#ff7777" value="#111111"/> <Variable name="form.button.color" description="Button Color" type="color" default="#fff" value="#ffffff"/> <Variable name="form.button.font" description="Button Text Font" type="font" default="normal normal 12px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="normal normal 11px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="form.message.background" description="Message Background" type="color" default="#ff7777" value="#87ba45"/> <Variable name="form.message.color" description="Message Color" type="color" default="#fff" value="#ffffff"/> </Group> <Group description="Footer" selector="footer"> <Variable name="footer.background.color" description="Footer Background" type="color" default="#111" value="#111111"/> <Variable name="footer.color" description="Footer Color" type="color" default="#ccc" value="#cccccc"/> <Variable name="footer.link.color" description="Footer Link Color" type="color" default="#999" value="#999999"/> <Variable name="footer.link.hover.color" description="Footer Hover Color" type="color" default="#888" value="#888888"/> <Variable name="footer.widget.title.color" description="Widget Title Color" type="color" default="#fff" value="#ffffff"/> <Variable name="footer.widget.title.border" description="Title Border Color" type="color" default="#444" value="#444444"/> <Variable name="footer.widget.span.border" description="Title Span Color" type="color" default="#ff7777" value="#ff7777"/> <Variable name="widget.title.font" description="Widget Title Font" type="font" default="700 12px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="normal bold 16px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="footer.border.background" description="Border Color" type="color" default="#222" value="#222222"/> </Group> <Group description="Footer Social Buttons" selector="social"> <Variable name="button.background.color" description="Button Background" type="color" default="#333" value="#333333"/> <Variable name="button.background.hover.color" description="Button Hover Background" type="color" default="#ff7777" value="#87ba45"/> <Variable name="fa.button.color" description="Button Color" type="color" default="#fff" value="#ffffff"/> <Variable name="fa.button.hover.color" description="Button Hover Color" type="color" default="#fff" value="#ffffff"/> </Group> <Group description="Subscribe Form" selector="follow"> <Variable name="follow.button.color" description="Follow Button Color" type="color" default="#fff" value="#ffffff"/> <Variable name="follow.button.background" description="Follow Button Background" type="color" default="#333" value="#333333"/> <Variable name="follow.button.border" description="Follow Border Color" type="color" default="#555" value="#555555"/> <Variable name="follow.button.font" description="Button Text Font" type="font" default="normal normal 12px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="normal normal 12px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="follow.button.hover" description="Button Hover" type="color" default="#ff7777" value="#87ba45"/> <Variable name="follow.form.background" description="Button Background" type="color" default="#333" value="#333333"/> <Variable name="follow.form.border" description="Border Color" type="color" default="#555" value="#555555"/> <Variable name="follow.form.color" description="Form Color" type="color" default="#fff" value="#ffffff"/> </Group> <Group description="Footer Widgets" selector="widgets"> <Variable name="popular.title.font" description="Popular Title Font" type="font" default="400 14px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="normal normal 18px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="popular.text.font" description="Popular Text Font" type="font" default="normal normal 12px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="normal normal 13px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="popular.date.font" description="Popular Date Font" type="font" default="italic 700 13px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="italic normal 13px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="popular.date.color" description="Popular Date Color" type="color" default="#fff" value="#ffffff"/> <Variable name="featured.title.font" description="Featured Title Font" type="font" default="400 14px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="normal normal 18px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="featured.text.font" description="Featured Text Font" type="font" default="normal normal 12px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="normal normal 13px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="featured.rm.font" description="Featured Read More Font" type="font" default="italic 700 13px system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, Helvetica, sans-serif" value="italic normal 14px system-ui, -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Arial, Helvetica, sans-serif"/> <Variable name="featured.rm.color" description="Featured Read More Color" type="color" default="#fff" value="#ffffff"/> </Group> */ button,input,select,textarea{font-family:inherit;font-size:100%;margin:0;}button,input{line-height:normal;}button,select{text-transform:none;}button,html input[type="button"],input[type="reset"],input[type="submit"]{-webkit-appearance:button;cursor:pointer;}button[disabled],html input[disabled]{cursor:default;}input[type="checkbox"],input[type="radio"]{box-sizing:border-box;padding:0;}input[type="search"]{-webkit-appearance:textfield;-moz-box-sizing:content-box;-webkit-box-sizing:content-box;box-sizing:content-box;}input[type="search"]::-webkit-search-cancel-button,input[type="search"]::-webkit-search-decoration{-webkit-appearance:none;}button::-moz-focus-inner,input::-moz-focus-inner{border:0;padding:0;}textarea{overflow:auto;vertical-align:top;} h2.date-header { display: block; margin: 0 0 24px; color: #475569; font-size: 14px; line-height: 1.5; text-align: center; }
.feed-links { visibility: hidden; display: none; }
.hide { display: none; }
.widget,.section,#main { margin: 0; padding: 0!important; }
.no-padding { padding: 0 !important; }
.widget ul, .widget li, .BlogArchive #ArchiveList ul.flat li { padding: 0; }
.cookie-choices-info { background-color: rgba(0, 0, 0, 0.9)!important; bottom: 0!important; top: auto!important; }
.cookie-choices-info .cookie-choices-text { color: #fff!important; font-size: 10px!important; line-height: 1.2em!important; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif!important; }
.cookie-choices-info .cookie-choices-button { font-weight: 400!important; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif!important; font-size: 10px!important; text-transform: none!important; color: #fff!important; background-color: #ff7777!important; padding: 5px 10px!important; border-radius: 3px!important; }
h1, h2, h3, h4, h5, h6, .h1, .h2, .h3, .h4, .h5, .h6 { font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif; line-height: 1.2em; font-weight: 300; color: #222222; }
h1, .h1 { font-size: 36px; }
h2, .h2 { font-size: 30px; }
