h6, .h6 { font-size: 12px; }
html, body { margin: 0; padding: 0; height: 100%; width: 100%; }
*:active, *:focus { outline: none; }
body { font: $(body.font); background: $(body.background); color: $(body.color); overflow-x: hidden; overflow-y: scroll; }
a { color: $(link.color); }
a:hover { color: $(link.color.hover); text-decoration: none; }
/* Navbar ----------------------------------------------- */ .header-nav { transition: all .5s ease; margin: 0; /* Tetap berada di atas slider, termasuk saat navbar mengecil ketika scroll. */ z-index: 1030; }
.navbar-inverse { background-color: $(header.background); border: none; border-bottom: 1px solid #eee; }
.top-nav-collapse { background-color: $(header.background); }
.navbar-header { padding: 0 0 0 30px; }
.navbar-header h1 { position: relative; font: $(blogtitle.font); color: $(blogtitle.color); margin: 0; padding: 0; line-height: 43px; }
.navbar-header img { height: 50px; width: auto; }
.top-nav-collapse img { height: 35px; margin-top: 7.5px; }
.navbar-header h1 a { color: $(blogtitle.color); text-decoration: none; }
.top-nav-collapse h1 { margin-top: 24px; -webkit-transform: translateY(-50%) scale(0.7); transform: translateY(-50%) scale(0.7); margin-left: -15px; }
.navbar-inverse .navbar-nav>li>a { color: $(menu.color); text-shadow: 1px 1px 0 rgba(0,0,0,0.3); font: $(menu.font); line-height: 19px; }
.main-menu { position: relative; z-index: 2; }
.main-menu ul > li { float: left; position: relative; list-style: none; }
.main-menu ul > li > a { font: $(menu.font); color: $(menu.color); line-height: 51px;
margin: 0 15px 0; display: block; text-decoration: none; }
.main-menu ul > li > ul { position: absolute; background-color: $(header.background); top: 52px; min-width: 150px; padding: 0; margin-left: -10px; z-index: 99; border: 1px solid rgba(0, 0, 0, 0.1); margin-top: -1px; visibility: hidden; opacity: 0; transition: all .5s ease-in-out; -webkit-transform: translateY(15px); -moz-transform: translateY(15px); transform: translateY(15px); }
.main-menu ul > li > ul > li > ul { position: absolute; top: 0; left: 150px; width: 150px; background-color: $(header.background); padding: 0; z-index: 99; border: 1px solid rgba(255,255,255,0.1); visibility: hidden; opacity: 0; -webkit-transform: translateY(15px); -moz-transform: translateY(15px); transform: translateY(15px); }
.main-menu ul > li > ul > li { display: block; float: none; position: relative; }
.main-menu ul > li > ul > li a { font-size: 13px; margin: 0; padding: 0 15px; display: block; color: $(menu.color); text-shadow: none; line-height: 30px; text-decoration: none; }
.main-menu ul > li.parent > a:after { font-family: "Font Awesome 7 Free"; font-weight: 900; content: "\f107"; float: right; margin-left: 5px; }
@media all and (-ms-high-contrast: none), (-ms-high-contrast: active) { .main-menu ul > li a { float: left; }
.main-menu ul > li.parent > a:after { float: right!important; } }
.main-menu ul li a:hover { color: $(hover.menu.color); }
.main-menu ul > li:hover > ul, .main-menu ul > li > ul > li:hover > ul { opacity: 1; visibility: visible; -webkit-transform: translateY(0); -moz-transform: translateY(0); transform: translateY(0); }
.main-menu ul > li > ul > li.parent > a:after { font-family: "Font Awesome 7 Free"; font-weight: 900; content: "\f105"; float: right; }
@media (max-width: 992px) { .main-menu ul > li > a, .main-menu ul > li { line-height: 35px; background-color: $(header.background); float: none; }
.main-menu ul > li.parent > a:after { float: none; display: none; }
.main-menu ul > li > ul, .main-menu ul > li > ul > li > ul { position: relative; opacity: 1!important; visibility: visible; top: 0; left: 25px; margin-left: 0; border: 0; max-width: 200px; -webkit-transform: none; -moz-transform: none; transform: none; }
}
