/* Main Slider ----------------------------------------------- */ .fp-slider .widget-content, .fp-slides .widget.HTML{ width: 100%; max-width: 100%; height: 100%; max-height: 100%; overflow: hidden; }
.fbt-slide-img, .fp-slides .widget > h2.title { display: none; }
.fp-slider { position: relative; isolation: isolate; z-index: 1; width: 100%; max-width: 100%; height: 500px; max-height: 500px; overflow: hidden; background: #000; margin-top: 90px; }
.fp-content-wrap, .fp-slides-items, .fp-slides-container, .fp-slides { width: 100%; height: 100%; max-width: 100%; max-height: 100%; }
.fp-thumbnail, .fp-prev-next-wrap { width: 100%; height: 100%; max-height: 100%; max-width: 100%; }
.fbt-resize, .fp-slides .fp-thumbnail { height: 100%; width: 100%; max-width: 100%; max-height: 100%; }
.fp-slides .fp-thumbnail img { width: 100%; height: 100%; max-height: 100%; }
.fp-title-box { position: relative; *text-align: center; display: table-cell; vertical-align:middle; }
.fp-slides-items { position: relative; }
/* CLS mobile: ruang slider dan posisi setiap widget ditetapkan sebelum jQuery Cycle berjalan. Plugin hanya mengubah opacity, bukan koordinat. */ #main-slider { position: relative; width: 100%; height: 100%; min-height: 500px; margin: 0; padding: 0; overflow: hidden; }
#main-slider > .widget.HTML { position: absolute !important; top: 0 !important; right: 0 !important; bottom: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important; min-height: 500px !important; margin: 0 !important; padding: 0 !important; }
#main-slider > .widget.HTML:not(#HTML1) { display: none; opacity: 0; }
#main-slider > #HTML1 { display: block; opacity: 1; z-index: 2; }
/* Setiap HTML/JavaScript pada MAIN-SLIDER diperlakukan sebagai satu slide. Aturan ini menjaga slide tambahan tetap setinggi area slider dan mencegah isi widget tampil sebagai blok biasa di atas latar hitam. */ #main-slider > .widget.HTML, #main-slider > .widget.HTML > .widget-content, #main-slider > .widget.HTML .fp-slides-items { width: 100%; height: 100%; min-height: 100%; }
#main-slider h2.fp-title, #main-slider h3.fp-title { display: block !important; }
h1.fp-title, h3.fp-title { color: $(slider.color); font: $(slidertitle.font); text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3); line-height: .85em; padding: 0; margin-bottom: 20px; }
h3.fp-title span { color: #fff; }
h1.fp-title a, h3.fp-title a { color: $(slider.color); text-decoration: none; }
.fp-content { position: absolute; top: 0; line-height: 24px; width: 100%; max-width: 100%; padding: 0; overflow: hidden; height: 100%; display: table; }
.fp-content p { font-size: 17px; font: $(slider.text); color: $(slider.color); text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3); width: 100%; padding: 0; margin: 0 auto 32px; line-height: 26px; text-transform: none; }
.fp-prev-next { position: absolute; }
.fp-prev { position: absolute; bottom: 45%; left: 30px; width: 50px; height: 80px; cursor: pointer; background: rgba(0, 0, 0, 0.5) url('https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgyMogbxfJ-GGJirVEM6AsnGcNdAXj1ETA7T2qkqC5W-YESylxqkN43gSa8z0egUkOKsXijrCTJ2Ku8ptW89zgnXsIZn54zN0-pSOBpPepyas1Rk2E7edMbKZ924_i8Vz5N8TAXls3aiSGq/s1600/slider-arrows.png') no-repeat center left; visibility:hidden; transition: all 0.5s ease; z-index: 999; }
.fp-prev:hover { opacity: 0.9; filter: alpha(opacity = 80); }
.fp-next { position: absolute; bottom: 45%; right: 30px; width: 50px; height: 80px; cursor: pointer; background: rgba(0, 0, 0, 0.5) url('https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgyMogbxfJ-GGJirVEM6AsnGcNdAXj1ETA7T2qkqC5W-YESylxqkN43gSa8z0egUkOKsXijrCTJ2Ku8ptW89zgnXsIZn54zN0-pSOBpPepyas1Rk2E7edMbKZ924_i8Vz5N8TAXls3aiSGq/s1600/slider-arrows.png') no-repeat center right; visibility:hidden; transition: all 0.5s ease; z-index: 999; }
.fp-slides:hover .fp-prev, .fp-slides:hover .fp-next { visibility: visible; transition:all .2s ease-in-out; }
@media (max-width: 1024px) { .fp-next{right: 15px;} .fp-prev{left: 15px;} }
.fp-next:hover { opacity: 0.8; filter: alpha(opacity = 80); }
.fbt-slide-nav { text-align: center; position: absolute; bottom: 200px; left: 50%; z-index: 9; width: 60%; padding-left: 0; margin-left: -30%; }
.fbt-slide-pager a { cursor: pointer; display: inline-block; float: none; height: 14px; width: 14px; background: $(pager.background); box-shadow: 1px 1px 0 rgba(0,0,0,0.3); line-height: 1; margin: 0 2px; overflow: hidden; padding: 0; text-indent: -999px; text-align: center; border-radius: 50%; }
.fbt-slide-pager a:hover, .fbt-slide-pager a.activeSlide { text-decoration: none; background: $(pager.hover.background); }
.fbt-overlay { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background-color: rgba(0, 0, 0, 0.2); background-repeat: repeat; }
.fp-thumbnail .fbt-overlay { background-color: rgba(0, 0, 0, 0); }
.fp-title-box .col-sm-6 { float: none; width: min(560px, calc(100% - 30px)); max-width: 560px; margin-left: 15px; border: 1px solid rgba(255, 255, 255, 0.18); border-radius: 4px; background-color: rgba(135, 186, 69, 0.72); box-shadow: 0 14px 36px rgba(0, 0, 0, 0.28); padding: 30px 35px 40px; }
/* Gaya isi slide dibuat umum. Konten setiap gadget MAIN-SLIDER tidak perlu lagi memakai selector khusus seperti #msp-home-slide-1. Karena itu slide kedua, ketiga, dan seterusnya dapat berisi teks berbeda tanpa kehilangan format judul, deskripsi, atau tombol. */ #main-slider .msp-slide-kicker { display: block; margin: 0 0 10px; color: #ffffff; font-family: inherit; font-size: 12px; font-weight: 700; letter-spacing: 0.08em; line-height: 1.4; text-transform: uppercase; text-shadow: 0 1px 3px rgba(0, 0, 0, 0.45); }
#main-slider h2.fp-title, #main-slider h3.fp-title { margin: 0 0 20px !important; padding: 0 !important; color: #ffffff !important; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif !important; font-size: 50px !important; font-style: italic; font-weight: 700 !important; line-height: 0.92 !important; text-shadow: 0 1px 3px rgba(0, 0, 0, 0.4); }
#main-slider .msp-slide-description { margin-bottom: 30px !important; }
#main-slider .msp-slide-actions { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }
#main-slider .msp-slide-actions .button { display: inline-flex !important; min-height: 42px; align-items: center; justify-content: center; margin: 0 !important; padding: 10px 22px !important; border-width: 2px !important; line-height: 1.3 !important; white-space: nowrap; text-shadow: none !important; }
#main-slider .msp-slide-primary { border-color: #f59e0b !important; background: #f59e0b !important; color: #14204a !important; box-shadow: 0 5px 14px rgba(20, 32, 74, 0.22); }
#main-slider .msp-slide-secondary { border-color: #14204a !important; background: #14204a !important; color: #ffffff !important; box-shadow: 0 5px 14px rgba(20, 32, 74, 0.28); }
#main-slider .msp-slide-primary:hover, #main-slider .msp-slide-primary:focus { border-color: #ffb72b !important; background: #ffb72b !important; color: #14204a !important; transform: translateY(-2px); }
#main-slider .msp-slide-secondary:hover, #main-slider .msp-slide-secondary:focus { border-color: #243a78 !important; background: #243a78 !important; color: #ffffff !important; transform: translateY(-2px); }
#main-slider .msp-slide-actions .button:focus-visible { outline: 3px solid #ffffff !important; outline-offset: 3px; }
/* Satu kontrol tetap berada di dalam slider, tidak ikut berpindah per slide. */ #main-slider .nav-slit { display: none !important; }
.msp-slider-controls .msp-slider-control { position: absolute; top: 50%; z-index: 8; display: inline-flex; width: 44px; height: 72px; align-items: center; justify-content: center; border: 0; background: rgba(135, 186, 69, 0.94); color: #ffffff !important; font-size: 38px; font-weight: 300; line-height: 1; text-decoration: none !important; transform: translateY(-50%); transition: background-color 160ms ease, opacity 160ms ease; }
.msp-slider-controls .msp-slider-prev { left: 0; border-radius: 0 4px 4px 0; }
.msp-slider-controls .msp-slider-next { right: 0; border-radius: 4px 0 0 4px; }
.msp-slider-controls .msp-slider-control:hover, .msp-slider-controls .msp-slider-control:focus { background: #6fa438; color: #ffffff !important; }
.msp-slider-controls .msp-slider-control:focus-visible { outline: 3px solid #ffffff; outline-offset: -5px; }
@media (max-width: 991px) { #main-slider h2.fp-title, #main-slider h3.fp-title { font-size: 40px !important; line-height: 1 !important; } }
@media (max-width: 767px) { .fp-title-box .container { width: 100%; padding-right: 0; padding-left: 0; }
.fp-title-box .row { margin-right: 0; margin-left: 0; }
.fp-title-box .col-sm-6 { width: calc(100% - 76px); max-width: none; margin: 0 auto; padding: 22px 20px 26px; }
#main-slider .msp-slide-kicker { font-size: 11px; letter-spacing: 0.05em; }
#main-slider h2.fp-title, #main-slider h3.fp-title { font-size: 29px !important; line-height: 1.15 !important; }
#main-slider .msp-slide-description { margin-bottom: 22px !important; }
#main-slider .msp-slide-actions { gap: 8px; }
#main-slider .msp-slide-actions .button { width: 100%; max-width: 280px; padding: 10px 14px !important; white-space: normal; }
.msp-slider-controls .msp-slider-control { width: 34px; height: 56px; font-size: 30px; } }
@media (prefers-reduced-motion: reduce) { #main-slider .msp-slide-actions .button, .msp-slider-controls .msp-slider-control { transition: none; } }
.fbt-overlay-dark { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background-color: rgba(0, 0, 0, 0.4); background-repeat: repeat; }
.fbt-overlay-light { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background-color: rgba(255, 255, 255, 0.8); background-repeat: repeat; }
@media (max-width:992px) { .fp-slider { margin-top: 50px; } }
@media (max-width: 736px) and (orientation: landscape) { .fp-slider { margin-top: 0; } }
@media (max-width:767px) { h1.fp-title, h3.fp-title, h1.fp-title a, h3.fp-title a { font-size: 29px; line-height: 1.2em!important; }
.fp-content p { font-size: 14px; line-height: 1.4em; } }
@media (max-width: 736px) and (orientation: landscape) { .fbt-slide-nav { top: 60px; bottom: auto; } }
/* Resize images ----------------------------------------------- */ .fbt-resize { width: 100%; max-width: 100%; height: 100%; max-height: 100%; background-position: center; -webkit-background-size: cover; -moz-background-size: cover; background-size: cover; -o-background-size: cover; -webkit-transition-duration: 1s; -moz-transition-duration: 1s; -o-transition-duration: 1s; }
/* Buttons ----------------------------------------------- */ a.button { border: 1px solid $(button.background); padding: 10px 40px; text-align: center; color: $(button.background); text-decoration: none; font: $(button.text); text-transform: uppercase; transition:all .2s ease-in-out; }
a.button.post { border-color: $(button.background); background: $(button.background); color: $(transbutton.color); margin-top: 30px!important; }
a.button.post:hover { border-color: $(transbutton.background)!important; color: $(transbutton.color); background: $(transbutton.background); }
a.button.trans { background: none; border: 1px solid $(transbutton.color); color: $(transbutton.color); }
a.button:hover { border-color: $(button.background); background: $(button.background); color: $(transbutton.color); }
a.button.trans:hover { border-color: $(transbutton.background)!important; color: $(transbutton.color); background: $(transbutton.background); }
/* Posts ----------------------------------------------- */ .blog-header { margin-top: 90px; margin-bottom: 65px; color: #fff; }
@media (max-width:992px) { .blog-header { margin-top: 50px; } } @media (max-width: 736px) and (orientation: landscape) { .blog-header { margin-top: 0; } }
.blog-header h1 { color: #fff; }
.blog-header p { color: #fff!important; margin-top: 20px!important; }
.blog-header .fbt-overlay { background: rgba(0, 0, 0, 0.4); }
/* Keep long post/page titles inside the dark header area. The original theme inherited a percentage height and hidden overflow from the generic parallax component, which could clip a two-line title. */ .blog-header.halfscreen { height: auto!important; min-height: 220px; }
.blog-header .content-a { display: flex; width: 100%; height: auto!important; min-height: 220px; align-items: center; overflow: visible; }
.blog-header .content-b { display: block; width: 100%; padding: 38px 0; }
.blog-header h1 { max-width: 100%; margin-top: 0; margin-bottom: 0; line-height: 1.25; overflow-wrap: anywhere; }
@media (max-width: 767px) { .blog-header.halfscreen, .blog-header .content-a { min-height: 190px; }
.blog-header .content-b { padding: 30px 0; }
.blog-header h1 { font-size: 28px; } }
.post img { max-width: 100%; margin: 15px 0!important; padding: 0; }
.post, .post-body { font: 400 15px system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif; line-height: 1.6em; }
/* Keep post cards/summaries centered, but use left alignment for article and page content. */ .post { text-align: center!important; }
.post-body { text-align: left!important; }
.post-body p { padding: 0 40px; }
/* Post and static-page content width Tablet/desktop: 80% viewport width with 10% space on each side. Mobile below 768px keeps the original responsive layout. */ @media (min-width: 768px) { body.item .msp-blog-container, body.static_page .msp-blog-container { width: 100%!important; max-width: none!important; }
body.item .msp-blog-container #wrap2, body.static_page .msp-blog-container #wrap2 { width: 100%; }
body.item .msp-blog-container #wrap2 > .col-sm-8.col-sm-offset-2, body.static_page .msp-blog-container #wrap2 > .col-sm-8.col-sm-offset-2 { float: none!important; width: 80%!important; margin-left: 10%!important; margin-right: 10%!important; }
body.item .msp-blog-container .post-body p, body.static_page .msp-blog-container .post-body p { padding-left: 0; padding-right: 0; } }
.meta, .post-meta { font: 700 16px system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif; color: #333; }
/* Metadata penulis dan waktu yang mengikuti opsi gadget Blog Posts. */ .msp-post-meta-row { display: flex; flex-wrap: wrap; gap: 6px 14px; align-items: center; justify-content: center; margin: 0; padding: 0; color: #475569; font-size: 13px; font-weight: 600; line-height: 1.55; }
.meta.post-meta .msp-post-meta-item, .meta.post-meta .msp-post-meta-item span { display: inline; }
/* Menetralisir pemisah otomatis tema agar nama penulis tidak diapit tanda "-". */ .meta.post-meta .msp-post-meta-item::before, .meta.post-meta .msp-post-meta-item::after, .meta.post-meta .msp-post-meta-item span::before, .meta.post-meta .msp-post-meta-item span::after { content: none !important; }
.msp-post-meta-label { margin-right: 4px; color: #64748b; font-weight: 500; }
.msp-post-meta-row a { color: #0a66c2; text-decoration: none; }
.msp-post-meta-row a:hover { color: #14204a; text-decoration: underline; text-underline-offset: 3px; }
/* Tautan kirim artikel melalui email. Ditampilkan hanya jika Blogger menyediakan data:post.emailPostUrl dari opsi Blog Posts. */ .msp-email-post-action { display: flex; width: 100%; justify-content: flex-start; margin: 18px 0; text-align: left; }
.msp-email-post-action a { display: inline-flex; min-height: 42px; gap: 9px; align-items: center; justify-content: center; padding: 9px 14px; border: 1px solid rgba(20, 32, 74, 0.18); border-radius: 8px; background: #f8fafc; color: #14204a; font-size: 13px; font-weight: 700; line-height: 1.4; text-decoration: none; }
.msp-email-post-action a:hover { border-color: #0a66c2; background: #eff6ff; color: #0a66c2; }
.msp-email-post-action a:focus-visible, .msp-author-profile a:focus-visible { outline: 3px solid #f59e0b; outline-offset: 3px; }
/* Profil penulis di bagian bawah artikel. Opsi tetap dikontrol dari Blog Posts > Show author profile below post. */ .msp-author-profile { display: grid; width: 100%; grid-template-columns: 72px minmax(0, 1fr); gap: 16px; align-items: center; margin: 26px 0 20px; padding: 18px; border: 1px solid rgba(20, 32, 74, 0.14); border-radius: 12px; background: #f8fafc; color: #334155; text-align: left; }
.msp-author-profile-no-photo { grid-template-columns: minmax(0, 1fr); }
.msp-author-profile-photo { display: block; width: 72px; height: 72px; margin: 0 !important; border: 0; border-radius: 50%; object-fit: cover; }
.msp-author-profile-avatar { display: inline-flex; width: 72px; height: 72px; align-items: center; justify-content: center; border-radius: 50%; background: #e2e8f0; color: #14204a; font-size: 26px; line-height: 1; }
.msp-author-profile-label { display: block; margin-bottom: 2px; color: #64748b; font-size: 11px; font-weight: 800; letter-spacing: 0.06em; line-height: 1.4; text-transform: uppercase; }
.msp-author-profile-name, .msp-author-profile-name a { color: #14204a; font-size: 17px; font-weight: 800; line-height: 1.4; text-decoration: none; }
.msp-author-profile-name a:hover { color: #0a66c2; text-decoration: underline; text-underline-offset: 3px; }
.msp-author-profile-description { margin: 7px 0 0 !important; padding: 0 !important; color: #475569; font-size: 13px; font-weight: 400; line-height: 1.65; }
@media (max-width: 480px) { .msp-post-meta-row { align-items: flex-start; flex-direction: column; }
.msp-author-profile { grid-template-columns: 56px minmax(0, 1fr); gap: 12px; padding: 15px; }
.msp-author-profile-no-photo { grid-template-columns: minmax(0, 1fr); }
.msp-author-profile-photo { width: 56px; height: 56px; }
.msp-author-profile-avatar { width: 56px; height: 56px; font-size: 21px; } }
/* Labels and geotag supplied by the Blogger Blog Posts gadget. */ .msp-post-taxonomy { display: flex; width: 100%; flex-wrap: wrap; gap: 10px 18px; align-items: center; margin: 24px 0 4px; padding: 14px 0; border-top: 1px solid rgba(20, 32, 74, 0.14); border-bottom: 1px solid rgba(20, 32, 74, 0.14); color: #475569; font-size: 13px; line-height: 1.55; text-align: left; }
.msp-post-taxonomy-item { display: inline-flex; min-width: 0; flex-wrap: wrap; gap: 5px; align-items: baseline; }
.msp-post-taxonomy-title { color: #14204a; font-weight: 700; }
.msp-post-taxonomy a { color: #0a66c2; text-decoration: none; }
.msp-post-taxonomy a:hover { color: #14204a; text-decoration: underline; text-underline-offset: 3px; }
@media (max-width: 600px) { .msp-post-taxonomy { align-items: flex-start; flex-direction: column; } }
.post-separator { width: 100%; height: 1px; background: rgba(0, 0, 0, 0.1); margin: 30px 0; }
hr { border: 0; height: 1px; background-image: linear-gradient(to right,rgba(0,0,0,0),rgba(0,0,0,.75),rgba(0,0,0,0)); }
.pager li>a, .pager li>span { display: inline-block; padding: 9px 19px; background-color: #fff; border: 1px solid #ddd; border-radius: 15px; }
.related-posts ul { margin-left: -15px; margin-right: -15px; }
.related-posts ul li { list-style: none; float: left; padding-right: 15px; padding-left: 15px; margin-bottom: 30px; }
@media (min-width: 768px) { .related-posts ul li { width: 50%; } }
.error-404 { display: none; background: #fff; }
.error-404 h2 { font: 400 90px system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif; text-transform: uppercase; }
@media (max-width: 600px) { .error-404 h2 { font-size: 40px; } }
.error-404 p { margin-bottom: 35px!important; }
/* Share Button ----------------------------------------------- */ .post-share { float: left; width: 100%; margin: 25px auto 0; text-align: center; }
.post-share li,.post-sharing li { margin: 0 2px 2px 0; display: inline-block; font-size: 12px; }
ul.post-sharing:before { content: ''; display: block; margin-bottom: 5px; text-align: center; }
.post-share li a { position: relative; margin: 0 0 0 1px; padding: 4px 11px; line-height: 2.2; font-weight: 300; vertical-align: middle; color: #fff; font-size: 11px; text-transform: uppercase; display: inline-block; transition: background-color .3s; }
.post-share i { padding: 0 5px 0 0; top: 1px; font-size: 14px; position: relative; }
.post-share ul { list-style: none; }
.post-share ul li { padding-bottom: 3px; font-size: 11px; display: inline-block; margin-top: 5px; }
.post-footer .post-share li a { color: #fff; }
.post-sharing .facebook-share,a.facebook.df-share { background-color: #3B5998; }
.post-sharing .twitter-share,a.twitter.df-share { background-color: #000000; }
.post-sharing .whatsapp-share,a.whatsapp.df-whatsapp { background-color: #25D366; }
.post-sharing .threads-share,a.threads.df-threads { background-color: #000000; }
.post-sharing .linkedin-share,a.linkedin.df-linkedin { background-color: #0A66C2; }
.post-sharing .pinterest-share,a.pinterest.df-pinterest { background-color: #CB2027; }
.post-share li a:hover { color: #fff; background-color: #212026; }
/* Comments ----------------------------------------------- */ #comments { width: 100%; text-align: left; padding: 15px; margin-top: 0; border: 1px solid #ddd; }
#comments h3 { font-size: 25px; text-align: center; }
#comments .title-border { margin: 20px 0; }
#comments h4 { display: inline-block; padding: 10px; line-height: 40px; }
#comments h4,.comments .comment-header,.comments .comment-thread.inline-thread .comment { position: relative; }
#comments h4,.comments .continue a { background: #000; width: 100%; text-align: center; }
#comments h4,.comments .user a,.comments .continue a { font: normal 14px system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif; }
#comments h4,.comments .continue a { font-weight: normal; color: #fff; }
#comments .avatar-image-container img { background: #fff; border: 0; padding: 0; }
.comment-thread { font: normal 14px system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif; }
.comment-thread a { color: #777; }
.comment-thread ol { margin: 0 0 20px; }
.comment-thread .comment-content a,.comments .user a,.comments .comment-thread.inline-thread .user a { color: #000; font: normal 15px system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif; }
.comments .datetime { display: none; }
.comments .avatar-image-container,.comments .avatar-image-container img { width: 60px; max-width: 60px; height: 60px; max-height: 60px; }
.comments .comment-block,.comments .comments-content .comment-replies,.comments .comment-replybox-single { margin-left: 60px; }
.comments .comment-block,.comments .comment-thread.inline-thread .comment { border: 1px solid #ddd; background: #ffffff; padding: 20px; }
.comments .comments-content .comment { margin: 15px 0 0; padding: 0; width: 100%; line-height: 1em; }
.comments .comments-content .icon.blog-author { position: absolute; top: -20px; right: -20px; margin: 0; background-image: url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgvoZE-ZvJhqrMWz9HjuKikXLS2eRHa6Z2k9PqqjE2qWkkZcae8mrtZgrVfpKoWYTjW7QYcoC67yPXj7_1MNMwxC3v2SOw-GQD9THXvAvX0QAC_Wpo912xc8VjK6q6ScsVOP7lww9A2H3qm/s1600/comment-author-blue.gif); width: 36px; height: 36px; }
.comments .comment .comment-actions a { background: #000; padding: 4px 12px; color: #fff; font-size: 11px; font-weight: 300; text-transform: uppercase; border-radius: 3px; }
.comments .comment .comment-actions .item-control { margin-left: 3px; }
.comments .comments-content .inline-thread { padding: 0 0 0 20px; }
.comments .comments-content .comment-replies { margin-top: 0; }
.comments .comment-content { background: #f5f5f5; border: 1px solid #ddd; padding: 10px; font: normal 14px system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif; line-height: 1.4em; margin-bottom: 10px!important; }
.comments .comment-thread.inline-thread { background: transparent; }
.comments .comment-thread.inline-thread .comment { width: auto; }
.comments .comment-thread.inline-thread .comment:after { content: ""; position: absolute; top: 10px; left: -20px; width: 10px; height: 0px; }
.comments .comment-thread.inline-thread .comment .comment-block { border: 0; background: transparent; padding: 0; }
.comments .comment-thread.inline-thread .comment-block { margin-left: 75px; }
.comments .comment-thread.inline-thread .user a { font-size: 13px; }
.comments .comment-thread.inline-thread .avatar-image-container,.comments .comment-thread.inline-thread .avatar-image-container img { width: 60px; max-width: 60px; height: 60px; max-height: 60px; }
.comments .continue { border-top: 0; width: 100%; }
.comments .continue a { padding: 10px 0; text-align: center; }
.comment .continue { display: none; }
#comment-editor { background: #fff; width: 100%!important; }
.comment-form { width: 100%; max-width: 100%; }
/* Page Navigation ----------------------------------------------- */ .pagenav { clear: both; margin: 0 0 90px; padding: 0; text-align: center; font-size: 14px; }
.pagenav span,.pagenav a { padding: 9px 10px; display: inline-block; border: 1px solid #333; color: #111; margin-left: 0; margin-right: 5px; transition: all .2s ease-out; }
.pagenav .pages { color: #111; margin-right: 1px; }
.pagenav a { color: #111; }
.pagenav a:hover { color: #fff; text-decoration: none; background: #333; }
.pagenav .current { color: #fff; background: #333; }
/* Preloader ----------------------------------------------- */ .loader-mask { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background-color: rgb(255, 255, 255); z-index: 99999; }
.load-container { position: absolute; width: 70px; height: 70px; top: 50%; left: 50%; margin: -35px 0 0 -35px; }
.loader-cycle { width: 70px; height: 70px; position: absolute; top: 0; right: 0; bottom: 0; left: 0; z-index: 105; display: block; margin: auto; -webkit-transition: opacity .25s linear; transition: opacity .25s linear; }
.loader-cycle:before { border: 1px solid rgba(0,0,0,.1); }
.loader-cycle:before, .loader-cycle:after { width: 100%; height: 100%; position: absolute; top: 0; right: 0; bottom: 0; left: 0; border-radius: 110%; content: ''; display: block; }
.loader-cycle:after { -webkit-animation: .loader-cycl-spin .75s linear infinite; animation: loader-cycle-spin .75s linear infinite; border: 3px solid transparent; border-top-color: #e6c55d; }
.loader-cycle:before, .loader-cycle:after { width: 100%; height: 100%; position: absolute; top: 0; right: 0; bottom: 0; left: 0; border-radius: 110%; content: ''; display: block; }
@-webkit-keyframes loader-cycle-spin { from { -webkit-transform: rotate(0deg); transform: rotate(0deg); }
to { -webkit-transform: rotate(360deg); transform: rotate(360deg); } }
@keyframes loader-cycle-spin { from { -webkit-transform: rotate(0deg); transform: rotate(0deg); }
to { -webkit-transform: rotate(360deg); transform: rotate(360deg); } }
.cube { position: absolute; width: 50px; height: 50px; animation: rotate 1.5s infinite ease-out; z-index: 99999; }
.cube:before { content: ""; position: absolute; height: 14px; width: 50px; transform: skewX(60deg); top: -14px; left: -12px; }
.cube:after { content: ""; position: absolute; width: 25px; height: 50px; transform: skewY(30deg); top: -7px; right: 100%; }
.purple { background-color: #D47BF9; }
.purple:before { background-color: #8E44AD; }
.purple:after { background-color: #4C1C60; }
.orange { animation-delay: -0.75s; background-color: #FF8432; }
.orange:before { background-color: #FF7519!important; }
.orange:after { background-color: #863600!important; }
@keyframes rotate { 25% { transform: translate(50px, 0px); }
50% { transform: translate(50px, 50px); }
74% { z-index: 2; }
75% { transform: translate(0px, 50px); z-index: 4; } }
/* Popular Posts ----------------------------------------------- */ .widget.PopularPosts li { padding: 0; }
.PopularPosts ul li { list-style: none; position: relative; margin: 0; padding: 0; }
.PopularPosts .item-thumbnail { width: 120px; height: 100px; overflow: hidden; margin: 0 15px 0 0; }
.PopularPosts .item-thumbnail img { width: 100%; height: auto; margin: 0; padding: 0; }
.PopularPosts .item-title { padding-bottom: 0; }
.PopularPosts .item-title h5 a { margin: 0!important; padding: 0!important; line-height: 1.2em; font: $(popular.title.font)!important; }
.PopularPosts .item-snippet { margin: 0; padding: 0; font: $(popular.text.font); }
.PopularPosts .widget-content ul { margin: 0; padding: 0; }
.PopularPosts .widget-content ul li { padding: 2px 0; }
.PopularPosts .widget-content ul li:first-child { padding-top: 0; margin-top: -1px; }
.PopularPosts .meta { color: $(popular.date.color); font: $(popular.date.font); }
.PopularPosts .meta hr { display: none; }
.PopularPosts .meta p { margin: 0px 0 0!important; }
.PopularPosts .meta span { margin-right: 5px; }
.PopularPosts .meta .meta-comments, .PopularPosts .meta span.meta-author { display: none; }
/* Feature Post ----------------------------------------------- */ .FeaturedPost .post-summary { width; 100%; margin-bottom: 15px; }
.FeaturedPost h5 { font: $(featured.title.font); *text-align: center; }
.FeaturedPost p { font: $(featured.text.font); *text-align: center; }
.FeaturedPost a.r_more { font: $(featured.rm.font); color: $(featured.rm.color)!important; }
/* Labels ----------------------------------------------- */ .list-label-widget-content li { list-style-type: none; border-bottom: 1px solid #333; padding: 5px 0 7px; line-height: 0.7em; }
.list-label-widget-content li:first-child { padding-top: 1px; }
.list-label-widget-content li a { font-size: 13px!important; }
.list-label-widget-content li a { font-size: 13px; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif; }
.list-label-widget-content li span { float: right; }
.cloud-label-widget-content .label-size { font-size: 100%; float: left; }
.cloud-label-widget-content { margin-bottom: 50px!important; clear: both; padding: 0 0 30px; }
#footer-wrapper .cloud-label-widget-content .label-size a { color: #fff; float: left; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif; font-size: 13px; margin: 7px 5px 0 0; padding: 5px 8px; text-decoration: none; background-color: #444; }
#footer-wrapper .cloud-label-widget-content span.label-size a:hover { color: #fff!important; }
#footer-wrapper .label-size a:hover, .label-size:hover .label-count, .label-size:hover a { background-color: #f77; color: #fff!important; text-decoration: none; transition: all 0.2s ease-out 0s; }
.cloud-label-widget-content .label-size span { color: #999; float: left; font-size: 13px; margin: 0 5px 5px 0; padding: 5px; text-decoration: none; border: 1px solid #999; }
/* Slider Arrow Navigation ----------------------------------------------- */ .svg-wrap { position: absolute; width: 0px; height: 0px; overflow: hidden; }
.nav-slit a { position: absolute; top: 50%; display: block; outline: none; text-align: left; /* Cukup tinggi di dalam slider, tetapi tidak melampaui navbar (z-index 1030). */ z-index: 5; -webkit-transform: translateY(-50%); transform: translateY(-50%); }
.nav-slit a.prev { left: 0; }
.nav-slit a.next { right: 0; }
.nav-slit a svg { display: block; margin: 0 auto; padding: 0; }
/* Individual styles */
.nav-slit .icon-wrap { position: relative; display: block; padding: 45px 5px; background-color: $(arrows.background); }
.nav-slit svg.icon { -webkit-transition: -webkit-transform 0.3s 0.3s; transition: transform 0.3s 0.3s; fill: #fff; }
.nav-slit div { position: absolute; top: 0; width: 200px; height: 100%; background-color: $(arrows.background); -webkit-transition: -webkit-transform 0.3s 0.3s; transition: transform 0.3s 0.3s; -webkit-perspective: 1000px; perspective: 1000px; }
.nav-slit a.prev div { left: 0; -webkit-transform: translateX(-100%); transform: translateX(-100%); }
.nav-slit a.next div { right: 0; text-align: right; -webkit-transform: translateX(100%); transform: translateX(100%); }
.nav-slit h3 { position: absolute; top: 100%; margin: 0; padding: 0 20px; width: 100%; height: 30%; background: #34495e; color: #fff; text-transform: uppercase; white-space: nowrap; letter-spacing: 1px; font-weight: 500; font-size: 0.75em; line-height: 2.75; -webkit-transition: -webkit-transform 0.3s; transition: transform 0.3s; -webkit-transform: rotateX(-90deg); transform: rotateX(-90deg); -webkit-transform-origin: 50% 0; transform-origin: 50% 0; -webki-backface-visibility: hidden; -webkit-backface-visibility: hidden; backface-visibility: hidden; }
.nav-slit img { position: absolute; top: 0; left: 0; width: 100%; }
.nav-slit a:hover svg.icon { -webkit-transition-delay: 0s; transition-delay: 0s; }
.nav-slit a.prev:hover svg.icon { -webkit-transform: translateX(-100%); transform: translateX(-100%); }
.nav-slit a.next:hover svg.icon { -webkit-transform: translateX(100%); transform: translateX(100%); }
.nav-slit a:hover div { -webkit-transform: translateX(0); transform: translateX(0); }
.nav-slit a:hover h3 { -webkit-transition-delay: 0.6s; transition-delay: 0.6s; -webkit-transform: rotateX(0deg); transform: rotateX(0deg); }
/* Social Icons ----------------------------------------------- */ .fa-icon-wrap { margin: 0 auto; padding: 0; text-align: center; }
.fa-icon-wrap i { display: inline-block; font-size: 14px; cursor: pointer; text-align: center; position: relative; z-index: 1; color: #fff; text-transform: uppercase; background: none; margin: 0; padding: 0; }
.fa-icon-wrap a { margin: 0 2.5px; color: #fff; background: transparent; font-weight: normal; display: inline-block; text-align: center; position: relative; }
.fa-icon-wrap a:hover { color: #eee; }
.fa-icon-wrap a:hover i { color: #eee; }
/* Arrows ----------------------------------------------- */ .arrow-down { width: 0; height: 0; border-left: 30px solid transparent; border-right: 30px solid transparent; border-top: 30px solid #333333; margin: 0 auto; }
.arrow-down.light { border-top: 30px solid #ffffff; position: relative; }
.arrow-up { width: 0; height: 0; border-left: 30px solid transparent; border-right: 30px solid transparent; border-bottom: 30px solid #333333; margin: 0 auto; }
.arrow-up.light { border-bottom: 30px solid #ffffff; }
/* Services ----------------------------------------------- */ .services { margin: 0; padding: 80px 0 50px; background: $(service.background); }
.design { position: relative; padding: 0 20px!important; margin-bottom: 30px; }
.design .fa { cursor: pointer; width: 70px; height: 70px; line-height: 70px; text-align: center; position: relative; z-index: 1; color: $(fa.color); font-size: 28px; font-weight: normal; background: $(fa.background); border-radius:50%; margin-bottom: 15px; box-shadow: 0 0 0 0 rgba(255, 119, 119, 0.8); }
.design .fa:hover, .design .fa:active, .design .fa:focus { background: $(fa.hover); color: $(fa.hover.color); box-shadow: 0 0 0 30px transparent; -webkit-transition: box-shadow .4s ease-in-out; -moz-transition: box-shadow .4s ease-in-out; -o-transition: box-shadow .4s ease-in-out; -ms-transition: box-shadow .4s ease-in-out; transition: box-shadow .4s ease-in-out; }
.design .top { margin: 0 auto; text-align: center; }
.design h4 { line-height: 22px; color: $(service.title); margin: 0 0 10px; text-align: center; }
.design .bottom p{ text-align: center; color: $(service.text); font-size: 14px;
line-height: 1.6em.; }
.design a: hover { color: #ddd; }
/* General ----------------------------------------------- */ .col-title { text-align: center; margin-bottom: 30px; }
.col-title p, .our-story .col-title p { font-size: 17px; font-weight: 300; color: #333333; margin: 5px 0 0; }
.col-title h2 { text-align: center; padding: 0; margin: 0; }
.fbt-title-cloud { background: #333333; padding: 73px 0 43px; }
.fbt-title-cloud .col-title h2 { color: #ffffff; border: 0; padding: 0; }
.fbt-title-cloud .col-title p { color: #ffffff; }
/* Portfolio ----------------------------------------------- */ .portfolio { margin:0; padding:0; overflow: hidden; }
.portfolio .fbt-title-cloud { background: $(portfolio.title.background); padding: 73px 0 43px; }
.portfolio .fbt-title-cloud .col-title h2 { color: $(portfolio.title.color); border: 0; padding: 0; }
.portfolio .fbt-title-cloud .col-title p { color: $(portfolio.text.color); }
.portfolio .col-md-4.col-sm-6 .item:after { background: $(portfolio.image.background); content: ""; position: absolute; width: calc(100% - 30px); height: calc(100% - 30px); left: -100%; opacity: 0; transition: all 0.6s ease-in-out!important; }
.portfolio .col-md-4.col-sm-6:hover .item:after { top: 15px; left: 15px; display: block; transition: all 0.6s ease-in-out!important; opacity: .8; }
.portfolio .fbt-home-gallery .caption { position:absolute; top:43.5%; text-align:center; width:100%; visibility: hidden; }
.portfolio .col-md-4.col-sm-6:hover .caption { visibility: visible; }
.portfolio .fa-icon-wrap { margin: 0; text-align: center; }
.portfolio .fa-icon-wrap i { font-size: 15px; }
.portfolio .fa-icon-wrap a { width: 50px; height: 50px; line-height: 47px; color: $(portfolio.icons.color)!important; border: 1px solid $(portfolio.icons.color); border-radius: 50%; box-shadow: 0 0 0 0 rgba(255, 255, 255, 0.8); z-index: 1; }
.portfolio .fa-icon-wrap a:active, .portfolio .fa-icon-wrap a:focus, .portfolio .fa-icon-wrap a:hover { background: $(portfolio.icons.hover.background); border-color: $(portfolio.icons.hover.background); box-shadow: 0 0 0 10px transparent; -webkit-transition: box-shadow .4s ease-in-out; -moz-transition: box-shadow .4s ease-in-out; -o-transition: box-shadow .4s ease-in-out; -ms-transition: box-shadow .4s ease-in-out; transition: box-shadow .4s ease-in-out; }
.portfolio .fa-icon-wrap i { color: $(portfolio.icons.color)!important; text-align: center; }
.portfolio .fa-icon-wrap a:hover i { color: $(portfolio.hover.icons.color)!important; }
.portfolio .col-md-4.col-sm-6 .item img { position: relative; }
.portfolio .col-md-4.col-sm-6 .item { *background: $(portfolio.image.background) url('https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiiW15pVDMwP8CaB7pdVucqeW6pXSn7XdG7FaGe9AZWjTaSKB-fTPucV8YndXOwG6InDPI2Ih19pGl4dmg24YkjL5sZnvlAEfW5pt_qXpftHA9juVUQZmOHNwaDLCAzWpKRYljWPjISkMND/s1600/plus.png') no-repeat center; position: relative; }
/* .portfolio .col-md-4.col-sm-6 .item img:hover { opacity: .4; transition: all 0.2s ease-in-out; } */
/* Our Team ----------------------------------------------- */ .our-story { padding: 73px 0 50px; background:$(about.background); }
.our-story .col-title p { font: $(title.description.font); color: $(about.title.description); }
.col-title h2 { color: $(about.title.color); }
.our-story h3.name { font: $(name.font); text-align: center; margin: 20px 0px 5px; color: $(name.font.color); }
.our-story h6 { font: $(activity.font); text-align: center; color: $(ctivity.font.color); text-transform: uppercase; margin-bottom: 15px; }
.our-story p { font: $(about.text.font); text-align: center; margin: 0 0 15px; color: $(about.text.color); }
.our-story .fa-icon-wrap { margin: 0; text-align: center; }
.our-story .fa-icon-wrap a { width: 30px; height: 30px; line-height: 27px; color: $(icons.color)!important; border: 1px solid $(icons.color); border-radius: 50%; box-shadow: 0 0 0 0 rgba(0, 0, 0, 0.8); }
.our-story .fa-icon-wrap a:active, .our-story .fa-icon-wrap a:focus, .our-story .fa-icon-wrap a:hover { background: $(icons.hover.background); box-shadow: 0 0 0 10px transparent; -webkit-transition: box-shadow .4s ease-in-out; -moz-transition: box-shadow .4s ease-in-out; -o-transition: box-shadow .4s ease-in-out; -ms-transition: box-shadow .4s ease-in-out; transition: box-shadow .4s ease-in-out; }
.our-story .fa-icon-wrap i { color: $(icons.color)!important; }
.our-story .fa-icon-wrap a:hover i { color: $(icons.hover.color)!important; }
/* Dimensions &amp; Settings ----------------------------------------------- */ .gl { height: 100%; max-height: 100%; }
.gl-slider { height: 100%; max-height: 100%; }
.gl-header { height: 500px; }
.gh { height: 50%; max-height: 50%; overflow: hidden; }
.op { padding-top: 120px; padding-bottom: 90px; }
.om { padding: 120px 0; }
.fbt-g { margin-bottom: 30px; }
.an { margin-top: 40px; }
.am {padding:50px 0;}
.un { margin-bottom: 40px; }
.teston { padding: 80px 0; }
.img-m { margin-bottom: 15px; }
.og { padding: 80px 0 50px; }
.on { padding: 150px 0 120px; }
.no-padding { padding: 0 !important; }
.padding-1 { padding: .5px!important; }
.no-margin { margin: 0!important; }
/* Custom Lightbox ----------------------------------------------- */ body.hidden-scroll { overflow: hidden; }
.sl-overlay { position: fixed; left: 0; right: 0; top: 0; bottom: 0; background: rgba(0, 0, 0, 0.9); display: none; z-index: 9990; }
.sl-wrapper { z-index: 1000; }
.sl-wrapper button { border: none!important; background: transparent; font-size: 24px; padding: 0; cursor: pointer; }
.sl-wrapper button:hover { opacity: 0.7; }
.sl-wrapper .sl-close { display: none; position: fixed; right: 50px; top: 40px; z-index: 9991; border: none!important; color: #fff; }
.sl-wrapper .sl-close:focus { border: none!important; }
.sl-wrapper .sl-counter { position: fixed; top: 40px; left: 40px; z-index: 9991; color: #fff; }
.sl-wrapper .sl-navigation { width: 100%; display: none; }
.sl-wrapper .sl-navigation button { position: fixed; top: 50%; margin-top: -10px; height: 30px; width: 30px; line-height: 30px; text-align: center; display: block; z-index: 9991; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif; }
.sl-wrapper .sl-navigation button.sl-next { right: 40px; font-size: 40px; color: #fff; }
.sl-wrapper .sl-navigation button.sl-prev { left: 40px; font-size: 40px; color: #fff; }
.sl-wrapper .sl-image { position: fixed; -ms-touch-action: none; touch-action: none; z-index: 10000; }
.sl-wrapper .sl-image img { margin: 0; padding: 0; display: block; }
.sl-wrapper .sl-image iframe { border: 0 none; background: #000; }
.sl-wrapper .sl-image .sl-caption { display: none; padding: 10px; color: #fff; background: #000; opacity: 0.8; position: absolute; bottom: 0; left: 0; right: 0; }
.sl-wrapper .sl-image .sl-caption.pos-top { bottom: auto; top: 0; }
.sl-wrapper .sl-image .sl-caption.pos-outside { bottom: auto; }
.sl-wrapper .sl-image .sl-download { display: none; position: absolute; bottom: 5px; right: 5px; color: #fff; z-index: 1005; }
.sl-spinner { display: none; border: 5px solid #333; border-radius: 40px; height: 40px; left: 50%; margin: -20px 0 0 -20px; opacity: 0; position: fixed; top: 50%; width: 40px; z-index: 1007; -webkit-animation: pulsate 1s ease-out infinite; -moz-animation: pulsate 1s ease-out infinite; -ms-animation: pulsate 1s ease-out infinite; -o-animation: pulsate 1s ease-out infinite; animation: pulsate 1s ease-out infinite; }
.sl-scrollbar-measure { position: absolute; top: -9999px; width: 50px; height: 50px; overflow: scroll; }
@-webkit-keyframes pulsate { 0% { transform: scale(0.1); opacity: 0.0; } 50% { opacity: 1; } 100% { transform: scale(1.2); opacity: 0; } } @keyframes pulsate { 0% { transform: scale(0.1); opacity: 0.0; } 50% { opacity: 1; } 100% { transform: scale(1.2); opacity: 0; } } @-moz-keyframes pulsate { 0% { transform: scale(0.1); opacity: 0.0; } 50% { opacity: 1; } 100% { transform: scale(1.2); opacity: 0; } } @-o-keyframes pulsate { 0% { transform: scale(0.1); opacity: 0.0; } 50% { opacity: 1; } 100% { transform: scale(1.2); opacity: 0; } } @-ms-keyframes pulsate { 0% { transform: scale(0.1); opacity: 0.0; } 50% { opacity: 1; } 100% { transform: scale(1.2); opacity: 0; } }
@media (max-width:991px) { .sl-wrapper .sl-navigation button.sl-next { right: 10px; }
.sl-wrapper .sl-navigation button.sl-prev { left: 10px; } }
/* Parallax ----------------------------------------------- */ .background { background-repeat: no-repeat; background-position: 50% 50%; background-position: 50% 50%\9 !important; position: relative; }
.fullscreen, .content-a { width: 100%; height: 100%; overflow: hidden; } .fullscreen.overflow, .fullscreen.overflow .content-a { height: auto; min-height: 100%; }
.content-a { display: table; }
.content-b { display: table-cell; position: relative; vertical-align: middle; text-align: center; }
.halfscreen { height: 70%; }
@media (max-width: 600px) { .halfscreen { height: 100%; } }
/* Clients ----------------------------------------------- */ .client { margin-bottom: 30px; }
#clients .col-title { padding: 73px 0 43px!important; }
.client-header { background: $(clients.title.background); }
.clients .arrow-down.light { border-top: 30px solid $(clients.title.background); }
.client-header .col-title h2 { color: $(clients.title.color); }
.client-header .col-title p { color: $(clients.text.color); }
/* HomePage - Blog ----------------------------------------------- */ .blog-content .grid-post .caption { padding: 18px 20px 10px; }
.blog-2 { padding: 72px 0 50px; background-color: $(blog.background); background-position: center; -webkit-background-size: cover; -moz-background-size: cover; background-size: cover; -o-background-size: cover; }
.blog-2 .col-title h2 { color: $(blog.title.color); }
.blog-2 .col-title p { color: $(blog.descrption.title.color); }
.blog-date { text-align: center; background: $(date.background); position: absolute; z-index: 1; top: 0px; padding: 5px 7px 5px; left: 0px; }
.day { color: $(day.color)!important; font-weight: 700; font-size: 19px; margin: 0; margin-bottom: 3px; }
.month { line-height: 8px; color: $(month.color)!important; font-size: 14px; text-transform: capitalize; font-weight: 500; }
.post-slider { max-width: 100%; width: 100%; position: relative; overflow: hidden; }
.img-credits { position: absolute; left: 0; right: 0; bottom: 0; padding: 15px 20px 8px; opacity: 1; transition: .25s; background: linear-gradient(to top,rgba(0,0,0,.6) 0,rgba(0,0,0,0) 100%); font-size: 13px; color: #fff; }
.img-credits a { color: #fff; }
.img-thumb { overflow: hidden; position: relative; }
.img-thumb:hover .img-credits { bottom: -20px; opacity: 0; }
.tags { text-align: left; float: left!important; margin-top: 10px; margin-bottom: 0; display:none; margin-right: 5px; }
.tags:first-child {display:block;}
.blog-2 .comments-1 { text-align: right; margin-top: 10px; }
.blog-2 .caption { border: 1px solid $(blog.caption.border); border-top: 0; background: $(blog.caption); padding-top: 25px; padding-bottom: 5px!important; }
.blog-2 .grid-post { margin-bottom: 30px; }
.blog-content .grid-post p { font: $(post.text.font); line-height: 1.4em; padding: 0 0px 20px; color: $(post.text.color); }
.blog-2 .grid-post h3 a, .blog-2 .grid-post h3 { font: $(post.title.font); color: $(post.title.color); line-height: 1.2em; text-decoration: none!important; margin-bottom: 15px; }
.blog-2 .grid-post a h3:active, .blog-2 .grid-post a h3:focus, .blog-2 .grid-post a h3:hover { color: $(post.title.hover.color)!important; text-decoration: none; }
.blog-2, .blog-content { padding-left: 0!important; padding-right: 0!important; }
@media (max-width:991px) { .blog-2 { background: none!important; } .blog-2 .caption { border: 0; } }
.grid-post h3, .grid-post p { text-align: center; }
.author-place { text-align: center; margin-bottom: 10px; }
span.author { color: $(author.color); text-transform: uppercase; font: $(author.font); }
span.author-text { margin-right: 5px; font: $(author.text); color: $(author.text.color); }
.fbt-title-cloud.attent.clearfix { padding: 40px 0; background: $(attent.background.color); }
.fbt-title-cloud.attent.clearfix .col-title { margin-bottom: 0; }
.fbt-title-cloud.attent.clearfix .col-title h2 { text-align: left!important; font: $(attent.text); line-height: 1.4em; color: $(attent.text.color); }
.fbt-title-cloud.attent.clearfix a.button.trans { margin-bottom: 0!important; float: right; border-color: $(attent.button.background); background: $(attent.button.background); display: table-cell; vertical-align: middle; }
.fbt-title-cloud.attent.clearfix a.button.trans:hover { color: $(attent.button.hover.color); background: none; border-color: $(attent.button.hover.border)!important; }
@media only screen and (max-width:991px) { .col-slogan h2.title { margin-left: 15px; padding-right: 15px; }
.fbt-title-cloud.attent.clearfix a.button.trans { float: left; margin: 15px 0 0 15px; } }
/* Contact Form ----------------------------------------------- */ .form-content { background: $(contact.background.color); padding: 73px 0; }
.contact-form-widget { padding: 0 30px; max-width: 100%; }
.c-form h2 { margin-bottom: 20px; color: $(form.title.color); }
.border { width: 165px; height: 15px; background: url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgdcxcF69_jJBHa_eMLslTKQkwnVb5ZxhRXNFfe03AFDgQ9yJHpGvX4Fi0Nrn5XHvWaXcjc4K8E-7FOHimpXH19bFvyqPLLA9odsxt5hyphenhyphentRpyCMHKbNmArAqI_6WlWJBokcoTzeIBfSQ57X/s1600/border.png); margin: 20px auto 25px; }
textarea, input { border: 1px solid $(form.border.color)!important; color: $(form.text.color); font: $(form.text.font); padding-top: 15px!important; }
input[type="text"] { color: $(form.text.color); }
.form-control { height: 50px; border-radius: 0; -webkit-box-shadow: none!important; box-shadow: none!important; margin-bottom: 30px; padding: 0px 12px 12px; color: $(form.text.color)!important; background: $(form.control.background.color); line-height: 1.6em; }
input[type="submit"] { padding: 9px 30px 9px!important; outline: none; color: $(form.button.color); text-transform: uppercase; font: $(form.button.font); transition: all 0.2s ease-in-out; -moz-transition: all 0.2s ease-in-out; -webkit-transition: all 0.2s ease-in-out; -o-transition: all 0.2s ease-in-out; margin-bottom: 12px!important; background: $(form.button.background); border-color: $(form.button.background)!important; }
.contact-form-button, .contact-form-button-submit { position: relative; border-radius: 0; vertical-align: middle; outline: none; min-height: 35px; line-height: 0px; font-size: 12px!important; }
input[type="submit"]:hover { background: $(form.button.background.hover)!important; border-color: $(form.button.background.hover)!important; }
.contact-form-error-message, .contact-form-error-message-with-border { background: $(form.message.background)!important; border: 0; bottom: 0; box-shadow: none; color: $(form.message.color); font-size: 12px; font-weight: 400!important; line-height: 29px; vertical-align: middle; margin-left: 0; opacity: 1; position: relative; text-align: center; }
.contact-form-success-message, .contact-form-success-message-with-border { background: $(form.message.background)!important; border: 0; bottom: 0; box-shadow: none; color: $(form.message.color); font-size: 12px; font-weight: 400; line-height: 29px; margin-left: 0; opacity: 1; position: static; text-align: center; }
/* Footer ----------------------------------------------- */ #footer-wrapper { background: $(footer.background.color); padding: 35px 0 10px; margin: -1px 0 0; color: $(footer.color); }
#footer-wrapper a { color: $(footer.link.color); }
#footer-wrapper a:hover { color: $(footer.link.hover.color)!important; }
#footer-wrapper .widget { margin-bottom: 20px; }
#footer-wrapper .section .widget h2 { color: $(footer.widget.title.color)!important; font: $(widget.title.font)!important; border-bottom: 1px solid $(footer.widget.title.border); padding-bottom: 10px; margin-bottom: 5px; }
#footer-wrapper .widget h2 span { padding:0 0 10px; border-bottom: 1px solid $(footer.widget.span.border); }
#footer-wrapper ul li { list-style: none; }
.footer-border { width: 100%; height: 1px; background: $(footer.border.background); margin: 0 0 30px; }
.footer-border.bottom { margin-top: 10px; margin-bottom: 28px; }
/* Footer LinkList ----------------------------------------------- */ #footer-wrapper .LinkList li { list-style-type: none; border-bottom: 1px solid #222; padding: 5px 0 7px; line-height: 0.7em; }
#footer-wrapper .LinkList li:first-child { padding-top: 1px; }
#footer-wrapper .LinkList li a { font-size: 13px!important; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif; }
@media (max-width: 768px) { #footer-wrapper { padding-left: 15px; padding-right: 15px; } }
/* Archive ----------------------------------------------- */ .BlogArchive #ArchiveList ul li { list-style: none; display: block; padding: 5px 0 5px 15px!important; text-decoration: none; font-size: 13px; }
#BlogArchive1_ArchiveMenu { width: 100%; border: 1px solid #555; background: #333; padding: 10px; margin: 8px 0 0; }
/* Copyrights ----------------------------------------------- */ .credit { text-align: center; font-size: 13px; padding: 0; margin: 0; }
.credit a { font: 700 15px system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, Helvetica, sans-serif; color: #fff!important; }
/* Footer Social Buttons ----------------------------------------------- */ #social-footer .fa-icon-wrap { text-align: right; }
#social-footer .fa-icon-wrap a i { font-size: 17px; color: $(fa.button.color); }
#social-footer .fa-icon-wrap a:hover i { color: $(fa.button.hover.color); }
#social-footer .fa-icon-wrap a { width: 45px; height: 45px; line-height: 46px; background: $(button.background.color); font-weight: normal normal; }
#social-footer .fa-icon-wrap a:hover { background: $(button.background.hover.color); }
@media (max-width: 768px) { #footer-wrapper .fa-icon-wrap { text-align: center!important; } }
/* Follow by email ----------------------------------------------- */ .follow-by-email-inner input[type="submit"] { padding: 9px 0px 9px!important; width: 100%; outline: none; color: $(follow.button.color); text-transform: uppercase; font: $(follow.button.font); transition: all 0.2s ease-in-out; -moz-transition: all 0.2s ease-in-out; -webkit-transition: all 0.2s ease-in-out; -o-transition: all 0.2s ease-in-out; margin-bottom: 12px!important; background: $(follow.button.background); border-color: $(follow.button.border)!important; border-left: 0!important; min-height: 45px; border-radius: 0 30px 30px 0; }
.follow-by-email-inner input[type="submit"]:hover { background: $(follow.button.hover)!important; border-color: $(follow.button.hover)!important; }
.follow-by-email-inner input[type="text"] { padding: 0 20px 0!important; background: $(follow.form.background); border-color: $(follow.form.border)!important; color: $(follow.form.color); min-height: 45px; border-radius: 30px 0 0 30px; }
/* Search ----------------------------------------------- */ #search { border: 1px solid #ddd; background: #fff url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjLljKhNRt-CEK_3-oNJ6yf3XMFI6JzeWiXfoX6Tp1UombewGTdV_NywwZGpBj1tJ_FDos3tcv6BSmR1NgCCDbkIapsfDbh4ekG9HRwRZfS2f2Oi3cyciy-nXdYAnts4Ow-MQEQaFX2_6Gn/s1600/search.png) 99% 50% no-repeat; text-align: left; padding: 6px 24px 6px 6px; margin-bottom: 40px; margin-top: 8px; }
#search #s { background: none; color: #979797; border: 0; width: 100%; outline: none; margin: 0; padding: 0; }
#search textarea, #search input { border: 0!important; }
#search input[type="text"] { padding-top: 5px!important; padding-bottom: 5px!important; }
.hidden {display: block!important;}

