function removeHtmlTag(strx,chop){var s=strx.split("<");for(var i=0;i<s.length;i++){if(s[i].indexOf(">")!=-1){s[i]=s[i].substring(s[i].indexOf(">")+1,s[i].length)}}s=s.join("");s=s.substring(0,chop-1);return s}
function mspEscapeHtml(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function mspPlainText(html) {
  var temporaryElement = document.createElement("div");
  temporaryElement.innerHTML = html || "";
  return (temporaryElement.textContent || temporaryElement.innerText || "")
    .replace(/\s+/g, " ")
    .trim();
}

function mspPostUrl(entry) {
  var links = entry.link || [];
  var index;

  for (index = 0; index < links.length; index += 1) {
    if (links[index].rel === "alternate") {
      return links[index].href;
    }
  }

  return "#";
}

function mspPostImage(entry) {
  var fallbackImage = window.imgr && imgr[0] ? imgr[0] : "";
  var thumbnail = entry.media$thumbnail && entry.media$thumbnail.url
    ? entry.media$thumbnail.url
    : fallbackImage;

  return thumbnail.replace(
    /\/s\d+(?:-[a-z0-9-]+)?\//i,
    "/w640-h360-p-k-no-nu/"
  );
}

function mspDispatchHomeBlogLoaded() {
  var feedEvent;

  if (typeof window.CustomEvent === "function") {
    feedEvent = new CustomEvent("mspHomeBlogLoaded");
  } else {
    feedEvent = document.createEvent("Event");
    feedEvent.initEvent("mspHomeBlogLoaded", true, true);
  }

  document.dispatchEvent(feedEvent);
}

function homeBlog(data) {
  var target = document.querySelector("#blog-content .widget-content");
  var entries = data && data.feed && data.feed.entry
    ? data.feed.entry
    : [];
  var monthNames = [
    "Jan", "Feb", "Mar", "Apr", "Mei", "Jun",
    "Jul", "Agu", "Sep", "Okt", "Nov", "Des"
  ];
  var summaryLimit = typeof summaryPost3 === "number" ? summaryPost3 : 130;
  var cards = [];

  if (!target) {
    return;
  }

  if (!entries.length) {
    target.innerHTML =
      '<p class="msp-insight-empty" role="status">' +
      "Belum ada artikel berlabel homepage." +
      "</p>";
    target.setAttribute("aria-busy", "false");
    return;
  }

  entries.slice(0, 3).forEach(function (entry) {
    var title = entry.title ? entry.title.$t : "Artikel PT MSP";
    var postUrl = mspPostUrl(entry);
    var summary = mspPlainText(entry.summary ? entry.summary.$t : "");
    var published = entry.published ? entry.published.$t : "";
    var day = published ? published.substring(8, 10) : "";
    var monthIndex = published
      ? parseInt(published.substring(5, 7), 10) - 1
      : -1;
    var month = monthNames[monthIndex] || "";
    var imageUrl = mspPostImage(entry);
    var safeTitle;
    var safeUrl;
    var safeImage;
    var safeSummary;

    if (summary.length > summaryLimit) {
      summary = summary
        .substring(0, summaryLimit - 1)
        .replace(/\s+\S*$/, "") + "…";
    }

    safeTitle = mspEscapeHtml(title);
    safeUrl = mspEscapeHtml(postUrl);
    safeImage = mspEscapeHtml(imageUrl);
    safeSummary = mspEscapeHtml(summary);

    cards.push(
      '<article class="col-md-4 grid-post">' +
        '<div class="img-thumb">' +
          '<div class="blog-date">' +
            '<span class="day">' + day + "</span><br/>" +
            '<span class="month">' + month + "</span>" +
          "</div>" +
          '<a aria-label="Buka artikel: ' + safeTitle + '" href="' + safeUrl + '">' +
            '<img alt="' + safeTitle + '" class="img-responsive" ' +
              'decoding="async" fetchpriority="low" height="360" ' +
              'loading="lazy" src="' + safeImage + '" width="640"/>' +
          "</a>" +
        "</div>" +
        '<div class="caption">' +
          '<a href="' + safeUrl + '"><h3>' + safeTitle + "</h3></a>" +
          "<p>" + safeSummary + ' <a href="' + safeUrl + '">[...]</a></p>' +
        "</div>" +
      "</article>"
    );
  });

  target.innerHTML = cards.join("");
  target.setAttribute("aria-busy", "false");
  mspDispatchHomeBlogLoaded();
}
