  });
  $('.fadeLeft').addClass("hidden").viewportChecker({
    classToAdd: 'visible animated fadeInLeft',
    offset: 100    
  });
  $('.fadeRight').addClass("hidden").viewportChecker({
    classToAdd: 'visible animated fadeInRight',
    offset: 100    
  });
});            
