//
/*
  Penyiapan slider dilakukan langsung saat HTML selesai diparsing,
  sebelum plugin Cycle dijalankan pada DOM ready. Dengan begitu widget
  HTML tambahan memiliki struktur slide yang sama dengan slide pertama.

  Pasangan konten dan gambar ditentukan berdasarkan URUTAN widget,
  bukan ID Image12/Image13 yang dapat berubah saat Blogger membuat
  gadget baru.
*/
(function () {
  'use strict';

  var slider = document.getElementById('main-slider');
  var imageArea = document.getElementById('main-slider-images');
  var controls = document.querySelector('.msp-slider-controls');

  if (!slider || !imageArea) {
    return;
  }

  function hasClass(element, className) {
    return (' ' + element.className + ' ').indexOf(' ' + className + ' ') !== -1;
  }

  function directWidgets(parent, widgetType) {
    var result = [];
    var children = parent.children;
    var index;

    for (index = 0; index < children.length; index += 1) {
      if (hasClass(children[index], 'widget') && hasClass(children[index], widgetType)) {
        result.push(children[index]);
      }
    }

    return result;
  }

  function createElement(tagName, className) {
    var element = document.createElement(tagName);
    element.className = className;
    return element;
  }

  var slideWidgets = directWidgets(slider, 'HTML');
  var imageWidgets = directWidgets(imageArea, 'Image');
  var slideIndex;

  for (slideIndex = 0; slideIndex < slideWidgets.length; slideIndex += 1) {
    var widget = slideWidgets[slideIndex];
    var widgetContent = widget.querySelector('.widget-content');
    var slideItems = widgetContent ? widgetContent.querySelector('.fp-slides-items') : null;

    if (!widgetContent) {
      continue;
    }

    if (!slideItems) {
      var originalContent = document.createDocumentFragment();

      while (widgetContent.firstChild) {
        originalContent.appendChild(widgetContent.firstChild);
      }

      slideItems = createElement('div', 'fp-slides-items');

      var thumbnail = createElement('div', 'fp-thumbnail');
      var overlay = createElement('div', 'fbt-overlay');
      var background = createElement('div', 'fbt-resize');
      thumbnail.appendChild(overlay);
      thumbnail.appendChild(background);

      var contentWrap = createElement('div', 'fp-content-wrap');
      var content = createElement('div', 'fp-content');
      var titleBox = createElement('div', 'fp-title-box');
      var container = createElement('div', 'container');
      var row = createElement('div', 'row');
      var panel = createElement('div', 'col-sm-6 fadeDown clearfix');

      panel.appendChild(originalContent);
      row.appendChild(panel);
      container.appendChild(row);
      titleBox.appendChild(container);
      content.appendChild(titleBox);
      contentWrap.appendChild(content);

      slideItems.appendChild(thumbnail);
      slideItems.appendChild(contentWrap);
      widgetContent.appendChild(slideItems);
    }

    var slideBackground = slideItems.querySelector('.fp-thumbnail .fbt-resize');

    if (slideBackground) {
      slideBackground.className = slideBackground.className.replace(/\bslide-\d+\b/g, '').replace(/\s+/g, ' ').replace(/^\s|\s$/g, '');
      slideBackground.className += ' slide-' + (slideIndex + 1);
    }
  }

  for (slideIndex = 0; slideIndex < imageWidgets.length; slideIndex += 1) {
    var image = imageWidgets[slideIndex].querySelector('.widget-content img');

    if (!image) {
      continue;
    }

    var imageSource = image.getAttribute('src');
    var targetBackgrounds = slider.querySelectorAll('.slide-' + (slideIndex + 1));
    var targetIndex;

    if (!imageSource) {
      continue;
    }

    for (targetIndex = 0; targetIndex < targetBackgrounds.length; targetIndex += 1) {
      targetBackgrounds[targetIndex].style.backgroundImage = 'url("' + imageSource.replace(/"/g, '%22') + '")';
      targetBackgrounds[targetIndex].style.backgroundPosition = 'center center';
      targetBackgrounds[targetIndex].style.backgroundSize = 'cover';
    }
  }

  if (controls && slideWidgets.length < 2) {
    controls.style.display = 'none';
  }
}());
