(function () {
  "use strict";

  var container = document.getElementById("msp-home-blog-feed");
  var feedLoaded = false;

  if (!container) {
    return;
  }

  function showFeedError() {
    container.setAttribute("aria-busy", "false");
    container.innerHTML =
      '<p class="msp-insight-empty" role="status">' +
      "Artikel belum dapat dimuat. Silakan muat ulang halaman." +
      "</p>";
  }

  function loadHomepageFeed() {
    var labelPath;
    var feedScript;

    if (feedLoaded) {
      return;
    }

    feedLoaded = true;
    labelPath = container.getAttribute("data-feed-label") || "/-/homepage";
    feedScript = document.createElement("script");
    feedScript.async = true;
    feedScript.src =
      "/feeds/posts/summary" +
      labelPath +
      "?max-results=3" +
      "&orderby=published" +
      "&alt=json-in-script" +
      "&callback=homeBlog";
    feedScript.onerror = showFeedError;
    feedScript.onload = function () {
      if (feedScript.parentNode) {
        feedScript.parentNode.removeChild(feedScript);
      }
    };
    document.head.appendChild(feedScript);
  }

  function scheduleHomepageFeed() {
    if ("requestIdleCallback" in window) {
      window.requestIdleCallback(loadHomepageFeed, {timeout: 2000});
    } else {
      window.setTimeout(loadHomepageFeed, 500);
    }
  }

  if (document.readyState === "complete") {
    scheduleHomepageFeed();
  } else {
    window.addEventListener("load", scheduleHomepageFeed, {once: true});
  }
}());
