(function () {
  'use strict';

  var section = document.getElementById('c-form');

  if (!section) {
    return;
  }

  var form = section.querySelector('form[name="contact-form"]');

  if (!form || form.getAttribute('data-msp-ready') === 'true') {
    return;
  }

  form.setAttribute('data-msp-ready', 'true');

  var nativeMessage = form.querySelector('textarea[name="email-message"]');

  if (!nativeMessage) {
    return;
  }

  function readField(key) {
    var element = form.querySelector('[data-msp-field="' + key + '"]');
    var value = element ? String(element.value || '').trim() : '';

    return value || '-';
  }

  function buildMessage() {
    var lines = [
      'FORMULIR KEBUTUHAN PT MITRA SOLUSINDO PRATAMA',
      '',
      'Jenis permintaan: ' + readField('requestType'),
      'Nama PIC: ' + readField('pic'),
      'Email: ' + readField('email'),
      'Perusahaan/instansi: ' + readField('company'),
      'Divisi/jabatan: ' + readField('position'),
      'Nomor WhatsApp: ' + readField('whatsapp'),
      'Kategori layanan: ' + readField('serviceCategory'),
      'Lokasi pekerjaan: ' + readField('location'),
      'Jumlah/luas/aset terkait: ' + readField('quantity'),
      'Target waktu: ' + readField('targetTime'),
      '',
      'RINGKASAN KEBUTUHAN',
      readField('summary'),
      '',
      'Halaman asal: ' + window.location.href,
      'Waktu pengiriman: ' + new Date().toLocaleString('id-ID')
    ];

    nativeMessage.value = lines.join('\n');
  }

  form.addEventListener('input', buildMessage, true);
  form.addEventListener('change', buildMessage, true);
  form.addEventListener('submit', buildMessage, true);

  buildMessage();
}());
